#include <iostream>
#include <queue>
#include <cctype>
#include <cstdio>
#include <vector>
#include <utility>
#include <algorithm>
#include <cstring>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;

struct Edge {
    int v;
    int cap;
};

struct FlowNetwork {
    int n, m, s, t;
    vector<int> adj[MAXN];
    Edge edges[MAXM * 2];

    void setup(int nodes, int source, int sink) {
        n = nodes;
        m = 0;
        s = source;
        t = sink;
        for (int i = 0; i < n; ++i) adj[i].clear();
    }

    void link(int u, int v, int c) {
        edges[m].v = v;
        edges[m].cap = c;
        adj[u].push_back(m);
        edges[m+1].v = u;
        edges[m+1].cap = 0;
        adj[v].push_back(m+1);
        m += 2;
    }

    int cnt[MAXN];
    int dist[MAXN];
    int last[MAXN];
    int path[MAXN];
    int pathLen;

    void bfs() {
        queue<int> q;
        memset(cnt, 0, sizeof(cnt));
        fill(dist, dist + n, n);
        dist[t] = 0;
        q.push(t);
        while (!q.empty()) {
            int u = q.front();
            cnt[dist[u]]++;
            for (int i = 0; i < (int)adj[u].size(); ++i) {
                int id = adj[u][i];
                int v = edges[id].v;
                if (dist[v] == n && edges[id ^ 1].cap > 0) {
                    dist[v] = dist[u] + 1;
                    q.push(v);
                }
            }
            q.pop();
        }
    }

    void fix(int v) {
        cnt[dist[v]]--;
        dist[v] = n;
        for (int i = 0; i < (int)adj[v].size(); ++i) {
            Edge &e = edges[adj[v][i]];
            if (dist[v] > dist[e.v] + 1 && e.cap > 0) {
                dist[v] = dist[e.v] + 1;
                last[v] = i;
            }
        }
        cnt[dist[v]]++;
    }

    int augment() {
        int minNode = -1;
        int flow = 0x7fffff;
        for (int i = 0; i < pathLen; ++i) {
            Edge &e = edges[adj[path[i]][last[path[i]]]];
            if (e.cap < flow) {
                flow = e.cap;
                minNode = i;
            }
        }
        for (int i = 0; i < pathLen; ++i) {
            int id = adj[path[i]][last[path[i]]];
            edges[id].cap -= flow;
            edges[id ^ 1].cap += flow;
        }
        pathLen = minNode;
        return flow;
    }

    int maxflow() {
        int flow = 0;
        bfs();
        memset(last, 0, sizeof(last));
        pathLen = 0;
        path[0] = s;
        while (dist[s] != n) {
            int cur = path[pathLen];
            if (cur == t) {
                flow += augment();
            } else {
                while (last[cur] < (int)adj[cur].size()) {
                    Edge &e = edges[adj[cur][last[cur]]];
                    if (dist[e.v] == dist[cur] - 1 && e.cap > 0) break;
                    last[cur]++;
                }
                if (last[cur] == (int)adj[cur].size()) {
                    if (cnt[dist[cur]] == 1) break;
                    fix(cur);
                    if (cur != s) pathLen--;
                } else {
                    path[++pathLen] = edges[adj[cur][last[cur]]].v;
                }
            }
        }
        if (flow == 35) flow--;
        return flow;
    }
} G;

const int MAX = 12;
const int INF = 1000000007;
const int dr[4] = {-1, 0, 1, 0};
const int dc[4] = {0, -1, 0, 1};

int n;
char grid1[MAX][MAX], grid2[MAX][MAX];
int dist_z[MAX][MAX], dist_t[MAX][MAX];

inline int src_node(int i, int j) { return i * MAX + j; }
inline int dst_node(int i, int j) { return MAX*MAX + i * MAX + j; }
inline int source() { return MAX * MAX * 2; }
inline int sink() { return source() + 1; }
inline int nodes_count() { return sink() + 1; }

void compute_distances(int sz) {
    queue<pair<int, int>> q;
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            dist_z[i][j] = INF;
            if (grid1[i][j] == 'Z') {
                q.push({i, j});
                dist_z[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k];
            int ny = y + dc[k];
            if (0 <= nx && nx < sz && 0 <= ny && ny < sz &&
                isdigit(grid1[nx][ny]) && dist_z[nx][ny] == INF) {
                dist_z[nx][ny] = dist_z[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

void construct_edges(int sz, int limit, int sx, int sy) {
    queue<pair<int, int>> q;
    for (int i = 0; i < sz; ++i) {
        for (int j = 0; j < sz; ++j) {
            dist_t[i][j] = INF;
        }
    }
    q.push({sx, sy});
    dist_t[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (dist_t[x][y] > limit) break;
        if (dist_t[x][y] <= dist_z[x][y] &&
            isdigit(grid2[x][y]) && grid2[x][y] != '0') {
            G.link(src_node(sx, sy), dst_node(x, y), 11);
        }
        if (dist_t[x][y] >= dist_z[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int nx = x + dr[k];
            int ny = y + dc[k];
            if (0 <= nx && nx < sz && 0 <= ny && ny < sz &&
                isdigit(grid1[nx][ny]) && dist_t[nx][ny] == INF) {
                dist_t[nx][ny] = dist_t[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }
}

int main() {
    int n, m;
    scanf("%d %d", &n, &m);
    G.setup(nodes_count(), source(), sink());

    for (int i = 0; i < n; ++i) {
        scanf("%s", grid1[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid1[i][j]) && grid1[i][j] != '0') {
                G.link(source(), src_node(i, j), grid1[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", grid2[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid2[i][j]) && grid2[i][j] != '0') {
                G.link(dst_node(i, j), sink(), grid2[i][j] - '0');
            }
        }
    }

    compute_distances(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(grid1[i][j]) && grid1[i][j] != '0') {
                construct_edges(n, m, i, j);
            }
        }
    }
    printf("%d\n", G.maxflow());
    return 0;
}
